     "**Njẹ ìyapa náà ń pọ̀ sí i bí orin náà ṣe ń lọ síwájú? Ìyẹn jẹ́ ìṣòro ìwọ̀n oṣùwọ̀n.** Nígbà tí iyara eré àti iyara ìgbékalẹ̀ yàtọ̀ sí ara wọn, àṣìṣe náà ń pọ̀ sí i sí òpin, èyí sì ń nílò ìwọ̀n tó bámu, kìí ṣe àtúnṣe àyè nìkan.",
     "**Àwọn ọ̀nà àbájáde nìkan ló ń dùn bí o bá lò wọ́n pọ̀.** Bọtìnì Space ń bẹ̀rẹ̀ àti dúró, Enter ń ṣe àmì ìlà lọ́wọ́lọ́wọ́, Z ń fagile ìlà kan — tẹ̀ Enter tààràtà nígbà eré dípò yíyípadà láàárín eku àti bọ́tìnnì ìtẹ̀.",
     "**Dídára ohùn ń ní ipa lórí péé péé.** Orisun pẹ̀lú ohùn tó mọ́ lójú rọrùn láti tẹ̀lé; àwọn ìgbékalẹ̀ ààyè àti àwọn orisun pẹ̀lú ohùn ẹ̀hìn tó ga ni ó nira ní gidi."
