   "desc": "Gbé orin wọlé, lẹ́mọ́ àwọn orin, tẹ̀ àmì àkókò kan fún ìlà kọ̀ọ̀kan bí o ṣe ń gbọ́, kí o sì gbé LRC tàbí SRT jáde. Space ń bẹ̀rẹ̀ àti dúró, Enter ń ṣe àmì ìlà, Z ń fagile, ọwọ́ dúró lori bọtìnì.",
