     "Lílẹ́mọ́ LRC tó ti wà tẹ́lẹ̀ náà ń ṣiṣẹ́ pẹ̀lú — àwọn àmì àkókò `[mm:ss.xx]` rẹ̀ ni a mọ̀, lẹ́yìn ìgbà tí o kó wọlé o tẹ̀ síwájú láti ìlà àkọ̀ọ̀lẹ̀ láìní àkókò, nítorí náà àwọn ìlà tí a ti ṣe àkókò tẹ́lẹ̀ kò nílò àtúnṣe."
