     "Ṣe àmì ìlà tí kò tọ́? Tẹ̀ Z láti fagile rẹ̀ kí o sì tún ṣe àmì rẹ̀. Bí o kò bá fẹ́ ṣe àmì ìlà kankan rárá (ìsinmi orin, àkókò orin nìkan), tẹ̀ \"Fò ìlà yìí\" kò sì ní hàn nínú ìgbéjáde."
