   "h1": "Ọ̀nà Méjì láti Ṣe Àwọn Àkọlé Èdè Méjì",
   "intro": "Àkọlé èdè méjì kan náà lè fi àwọn ìètò méjì tí ó yàtọ̀ pátápátá pamọ́. Kọ́ láti mọ ìyàtọ̀ wọn, kí o sì jẹ́ kí ṣíṣe, pípín, àti yíyípadà má ṣe jẹ́ kí o kọsẹ̀ mọ́.",
