     "Nigbati awọn faili meji ba ni nọmba kanna ti awọn titẹ sii ni aṣẹ kanna, sisọpọ nipasẹ aṣẹ ni o ni aabo julọ. Nigbati awọn nọmba ba yatọ (apa kan dapọ awọn titẹ sii, ekeji pin wọn), so pọ nipasẹ akoko ki o jẹ ki irinṣẹ baamu nipasẹ isunmọ. Ewo akoko lati lo da lori ewo faili ti o peye julọ — ni deede atilẹba.",
