   "desc": "Pín àwọn akọlé èdè méjì sí àwọn fáìlì méjì: orin ìpilẹ̀ṣẹ̀ àti orin ìtùmọ̀ ṣe ìgbàṣípò lọtọ̀ pẹ̀lú àwọn orúkọ ọ̀tọ̀ọ̀tọ̀; a mọ àwọn ìrísí méjèèjì. – AI-SRTSub",
