     "**Àwọn lẹ́tà tí ó darú**: fáìlì náà kìí ṣe UTF-8 — tún fipamọ́ bí UTF-8 nínú olóòtú rẹ̀. **Kò sí ohun tí ó hàn**: ṣàyẹ̀wò pé ìlà àkókò náà ń lò comma (kí í ṣe dot) àti pé nọ́mbà ẹ̀ka kò bájọ (ọ̀pọ̀ jù lọ àwọn ẹ̀rọ agbohùn ń gba àlàfo lọ́wọ́, àwọn kan kì í ṣe bẹ́ẹ̀). **Fáìlì náà jẹ́ HTML tàbí JSON**: orísun ìgbàṣọ̀lẹ̀ náà jẹ́ àṣìṣe; gbà á lẹ́ẹ̀kan sí i."
