     "**Kò sí ohun tí ó yípadà? Ṣàyẹ̀wò ṣáájú kí o tó bẹ̀rù**: tí barì ipò bá ròyìn 0 àwọn ìlà tí a yípadà, tàbí fáìlì náà kò ní lẹ́tà Ṣáínà tàbí a ti ṣe àìmọ̀ọ́mọ̀ mọ̀ ọ̀nà rẹ̀ — ṣàyẹ̀wò pé \"Detected format\" bá ohun tí o gbé wọlé mu."
